{
  "doc_type": "Merkblatt",
  "audience": "Eltern und Erziehungsberechtigte der 5. Klassen",
  "core": {
    "what": {
      "text": "Klassenlager der 5. Klassen vom 7. bis 11. Juni 2027 im Lagerhaus Sonnenhalde.",
      "segment_ids": ["s0001", "s0003"]
    },
    "must_do": {
      "text": "Gesuch bis 30. April 2027 einreichen, ausgefüllten Talon bis 23. April 2027 abgeben und die Rechnung innerhalb von 30 Tagen bezahlen.",
      "segment_ids": ["s0006", "s0013", "s0010"]
    },
    "deadline": {
      "text": "Gesuch bis 30. April 2027, Talon bis 23. April 2027, Rechnung innert 30 Tagen nach Lager.",
      "segment_ids": ["s0006", "s0013", "s0010"]
    },
    "cost": {
      "text": "Verpflegung CHF 16 pro Tag, insgesamt CHF 80.",
      "segment_ids": ["s0009"]
    },
    "contact": {
      "text": "Lagerleitung telefonisch 0791234567, Schulsekretariat Telefon 0441234570 oder E‑Mail sekretariat@schule-musterwil.example.",
      "segment_ids": ["s0027", "s0030"]
    }
  },
  "facts": [
    {
      "id": "f01",
      "kind": "deadline",
      "text": "Ein Gesuch muss bis 30. April 2027 schriftlich an die Schulleitung gerichtet werden.",
      "value_norm": "2027-04-30",
      "segment_ids": ["s0006"],
      "must_keep": true
    },
    {
      "id": "f02",
      "kind": "deadline",
      "text": "Der ausgefüllte Talon muss bis spätestens 23. April 2027 der Klassenlehrperson abgegeben werden.",
      "value_norm": "2027-04-23",
      "segment_ids": ["s0013"],
      "must_keep": true
    },
    {
      "id": "f03",
      "kind": "amount",
      "text": "Die Verpflegung kostet CHF 16 pro Tag.",
      "value_norm": "16",
      "segment_ids": ["s0009"],
      "must_keep": true
    },
    {
      "id": "f04",
      "kind": "amount",
      "text": "Die Gesamtkosten für die Verpflegung betragen CHF 80.",
      "value_norm": "80",
      "segment_ids": ["s0009"],
      "must_keep": true
    },
    {
      "id": "f05",
      "kind": "obligation",
      "text": "Die Rechnung wird nach dem Lager zugestellt und muss innerhalb von 30 Tagen bezahlt werden.",
      "value_norm": null,
      "segment_ids": ["s0010"],
      "must_keep": true
    },
    {
      "id": "f06",
      "kind": "obligation",
      "text": "Medikamente sind in Originalverpackung mit Dosierungsanweisung am Abreisetag der Lagerleitung zu übergeben.",
      "value_norm": null,
      "segment_ids": ["s0015"],
      "must_keep": true
    },
    {
      "id": "f07",
      "kind": "obligation",
      "text": "Die Teilnehmenden müssen ihren Unfall‑ und Haftpflichtversicherungsschutz prüfen.",
      "value_norm": null,
      "segment_ids": ["s0017"],
      "must_keep": true
    },
    {
      "id": "f08",
      "kind": "amount",
      "text": "Taschengeld darf höchstens CHF 20 betragen.",
      "value_norm": "20",
      "segment_ids": ["s0025"],
      "must_keep": true
    },
    {
      "id": "f09",
      "kind": "contact",
      "text": "Lagerleitung ist in dringenden Fällen unter der Nummer 0791234567 erreichbar.",
      "value_norm": "0791234567",
      "segment_ids": ["s0027"],
      "must_keep": true
    },
    {
      "id": "f10",
      "kind": "contact",
      "text": "Schulsekretariat ist telefonisch unter 0441234570 erreichbar.",
      "value_norm": "0441234570",
      "segment_ids": ["s0030"],
      "must_keep": true
    },
    {
      "id": "f11",
      "kind": "contact",
      "text": "E‑Mail des Schulsekretariats: sekretariat@schule-musterwil.example.",
      "value_norm": "sekretariat@schule-musterwil.example",
      "segment_ids": ["s0030"],
      "must_keep": true
    }
  ],
  "hard_terms": [
    {
      "term": "Klassenlager",
      "explanation": "Ein mehrtägiger Schulausflug für eine ganze Klasse, der zum Unterricht gehört.",
      "segment_ids": ["s0001", "s0003"]
    },
    {
      "term": "obligatorischer Schulanlass",
      "explanation": "Ein Ereignis, das für alle Schülerinnen und Schüler der Klasse verpflichtend ist.",
      "segment_ids": ["s0004"]
    },
    {
      "term": "Dispensation",
      "explanation": "Eine Befreiung von der Teilnahme, die nur aus wichtigen Gründen erteilt wird.",
      "segment_ids": ["s0005"]
    },
    {
      "term": "Talon",
      "explanation": "Ein Formular, das von den Eltern ausgefüllt und unterschrieben werden muss.",
      "segment_ids": ["s0013"]
    },
    {
      "term": "Haftpflichtversicherung",
      "explanation": "Eine Versicherung, die Schäden abdeckt, die man anderen zufügt.",
      "segment_ids": ["s0016"]
    }
  ],
  "omit_candidates": [
    {
      "segment_ids": ["s0012"],
      "reason": "Vertraulichkeitsvermerk, für die Eltern nicht notwendig."
    },
    {
      "segment_ids": ["s0032", "s0033", "s0034"],
      "reason": "Dankes- und Grußformeln, nicht zwingend für das Verständnis."
    },
    {
      "segment_ids": ["s0010"],
      "reason": "Detail zur Zahlungsfrist kann weggelassen werden, wenn die Kosten bereits genannt sind."
    }
  ]
}

{
  "repairs": [
    {
      "id": "b034",
      "texts": [
        "Wir senden die Post für Ihr Kind an das Lagerhaus Sonnenhalde, Bergstrasse 8, 7999 Musterberg."
      ]
    },
    {
      "id": "b029",
      "texts": [
        "Bei dringenden Fällen rufen Sie die Lagerleitung an.",
        "Die Lagerleitung ist die Person, die das Lager leitet. Sie ist unter 079 123 45 67 erreichbar."
      ]
    },
    {
      "id": "b027",
      "texts": [
        "Das detaillierte Programm finden Sie ab Mitte Mai unter www.schule-musterwil.example/lager.",
        "Die Packliste ist die Liste mit allen Dingen, die Sie einpacken müssen."
      ]
    }
  ],
  "additions": []
}

{
  "repairs": [
    {
      "id": "b003",
      "texts": [
        "Das Klassenlager der 5. Klassen findet vom 7. bis 11. Juni 2027 statt.",
        "Es ist im Lagerhaus Sonnenhalde, Bergstrasse 8, 7999 Musterberg."
      ]
    },
    {
      "id": "b006",
      "texts": [
        "Der ausgefüllte Talon muss bis 23. April 2027 abgegeben werden.",
        "Sie geben den Talon bei der Klassenlehrperson ab."
      ]
    },
    {
      "id": "b008",
      "texts": [
        "Medikamente müssen in Originalverpackung mit Dosierungsanweisung übergeben werden.",
        "Sie geben die Medikamente am Abreisetag der Lagerleitung ab."
      ]
    },
    {
      "id": "b020",
      "texts": [
        "Kopie von der Krankenkassenkarte"
      ]
    },
    {
      "id": "b023",
      "texts": [
        "Die Abreise ist am Montag um 7.15 Uhr.",
        "Sie treffen sich am Bahnhof Musterwil, Gleis 3."
      ]
    },
    {
      "id": "b024",
      "texts": [
        "Die Rückkehr ist am Freitag um ungefähr 16.30 Uhr am Bahnhof Musterwil."
      ]
    },
    {
      "id": "b026",
      "texts": [
        "Am Dienstag, 20. April 2027, um 19.30 Uhr findet ein Informationsabend statt.",
        "Er findet im Singsaal von dem Schulhaus Lindenhof statt."
      ]
    },
    {
      "id": "b027.1",
      "texts": [
        "Die Packliste enthält alle Dinge.",
        "Sie müssen diese Dinge einpacken."
      ]
    },
    {
      "id": "b029.1",
      "texts": [
        "Die Lagerleitung ist die Person.",
        "Sie leitet das Lager."
      ]
    },
    {
      "id": "b030",
      "texts": [
        "Das Schulsekretariat ist von Montag bis Freitag erreichbar.",
        "Es ist von 7.30 bis 11.30 Uhr 044 123 45 70 erreichbar."
      ]
    },
    {
      "id": "b033",
      "texts": [
        "Mobiltelefone bleiben zu Hause.",
        "Tablets bleiben zu Hause.",
        "Süssigkeiten bleiben zu Hause."
      ]
    },
    {
      "id": "b034",
      "texts": [
        "Wir senden die Post für Ihr Kind an das Lagerhaus Sonnenhalde.",
        "Die Adresse ist Bergstrasse 8, 7999 Musterberg."
      ]
    }
  ],
  "additions": []
}

